UPDATE tools SET
  best_for         = $d21h$יצירת תמונות פוטוריאליסטיות באיכות גבוהה עם קוד פתוח$d21h$,
  description      = $d21h$FLUX הוא מודל יצירת תמונות של Black Forest Labs, המציע איכות פוטוריאליסטית יוצאת דופן ומעקב מדויק אחר הוראות, זמין בגרסת קוד פתוח.$d21h$,
  description_long = $dl21h$FLUX.1 זכה להכרה נרחבת בקרב קהילת ה-AI כאחד ממודלי יצירת התמונות הטובים ביותר. בגרסאות dev ו-schnell הוא קוד פתוח, בעוד שגרסת pro מציעה את האיכות הגבוהה ביותר. מצטיין ביצירת תמונות עם טקסט נכון, אנטומיה מדויקת וקומפוזיציות מורכבות. נמצא בשימוש נרחב כבסיס למודלים מותאמים אישית עם fine-tuning ובפלטפורמות מקצועיות לייצור תמונות.$dl21h$,
  pros = ARRAY['איכות פוטוריאליסטית יוצאת דופן', 'גרסת קוד פתוח זמינה', 'יצירת טקסט מצוין בתוך תמונות', 'בסיס למודלים מותאמים אישית'],
  cons = ARRAY['דורש חומרה חזקה להרצה מקומית', 'גרסת Pro בתשלום', 'עקומת למידה לfine-tuning']
WHERE slug = 'flux' AND lang = 'he';

UPDATE tools SET
  best_for         = $d22h$עיצוב וקטורי ויצירת תמונות למותגים$d22h$,
  description      = $d22h$Recraft AI הוא כלי ייחודי ליצירת תמונות המתמחה בעיצוב גרפי מקצועי, עם תמיכה בפורמט SVG, אייקונים וקטוריים ועיצוב עקבי למותגים.$d22h$,
  description_long = $dl22h$Recraft מתמיין משאר מחוללי התמונות בהתמקדותו בעיצוב גרפי מקצועי. מאפשר יצירת תמונות בפורמט SVG (וקטורי) — יכולת ייחודית בשוק. פונקציית Brand Kit מאפשרת להגדיר צבעים, סגנונות ואלמנטים ויזואליים לשמירה על עקביות בכל היצירות. אידיאלי למעצבי UX/UI, צוותי שיווק ויוצרי תוכן הזקוקים לגרפיקה עקבית עם הזהות הויזואלית שלהם.$dl22h$,
  pros = ARRAY['תמיכה ב-SVG ווקטורים', 'Brand Kit לעקביות ויזואלית', 'אייקונים ואלמנטי UI', 'איכות גבוהה בעיצוב גרפי'],
  cons = ARRAY['פחות גמיש לאמנות קונספטואלית', 'ממשק פחות אינטואיטיבי למתחילים', 'קרדיטים מוגבלים ברמה החינמית']
WHERE slug = 'recraft-ai' AND lang = 'he';

UPDATE tools SET
  best_for         = $d23h$יצירת תמונות עם טקסט קריא ומעוצב בצורה מושלמת$d23h$,
