  pros = ARRAY['טקסט קריא ומעוצב בתמונות', 'שליטה על פלטת צבעים', 'אידיאלי לחומרי שיווק', 'ממשק קל מאוד לשימוש'],
  cons = ARRAY['פחות חזק בתמונות פוטוריאליסטיות מורכבות', 'פחות אפשרויות סגנון מ-Midjourney', 'מגבלות יומיות ברמה החינמית']
WHERE slug = 'ideogram' AND lang = 'he';

UPDATE tools SET
