  pros = ARRAY['וידאו פוטוריאליסטי באיכות גבוהה', 'סריקה ושחזור תלת-ממד', 'מצוין באפקטים פיזיקליים מורכבים', 'API זמין למפתחים'],
  cons = ARRAY['זמני יצירה איטיים', 'קרדיטים חינמיים מוגבלים', 'פונקציית ה-3D דורשת תנאי צילום טובים']
